rules.content:
/* Contract-compliant comparison reference adjustments (approved 2026-09-17). */
.btn,.input,.select,.search-input,.accordion-header,.sub-item,.tab,.header-search-trigger,.user-pill,.icon-rail .icon-btn,.ds-system-pill{box-sizing:border-box;min-height:44px}
.btn.icon,.icon-rail .icon-btn{min-width:44px}
.parity-contract-docs :is(button,input,select,textarea),.parity-contract-docs .docs-nav>div:first-child>a,.parity-contract-docs a.chip,.parity-contract-showcase :is(button,input,select,textarea),.parity-contract-showcase .parity-contract-switcher>a,.parity-contract-showcase .ds-shell footer a{box-sizing:border-box;min-height:44px}
.parity-contract-docs .docs-nav>div:first-child>a,.parity-contract-docs a.chip,.parity-contract-showcase .parity-contract-switcher>a,.parity-contract-showcase .ds-shell footer a{display:inline-flex;align-items:center}
.parity-contract-docs .docs-nav-item{white-space:normal}
.parity-contract-showcase .parity-contract-accent-targets{flex-wrap:wrap;max-width:100%}
.parity-contract-showcase .parity-contract-accent-target{display:inline-flex;width:44px;height:44px;flex:0 0 44px;align-items:center;justify-content:center;padding:0;border:0;border-radius:var(--radius-pill);background:transparent;cursor:pointer}
@media (min-width:768px) and (max-width:1024px){.mobile-menu-btn{display:none!important}}
@media (max-width:767px){
  .parity-contract-docs .docs-main,.parity-contract-showcase .ds-shell{box-sizing:border-box;min-width:0;max-width:100%}
  .parity-contract-docs .parity-contract-docs-spec>div{grid-template-columns:minmax(0,1fr)!important}
  .parity-contract-docs .parity-contract-docs-accent-palette{grid-template-columns:repeat(2,minmax(0,1fr))!important}
  .parity-contract-docs .parity-contract-docs-pager{grid-template-columns:repeat(2,minmax(0,1fr))!important}
  .parity-contract-docs .parity-contract-docs-pager>*{min-width:0;white-space:normal;overflow-wrap:anywhere}
  .parity-contract-docs .code-block{white-space:pre-wrap;overflow-wrap:anywhere}
  .parity-contract-docs a.chip,.parity-contract-showcase .btn,.parity-contract-showcase .tab{white-space:normal;overflow-wrap:anywhere}
}
@media (max-width:480px){
  .parity-contract-docs .table,.parity-contract-showcase .table{display:block;max-width:100%;overflow-x:auto}
  .parity-contract-showcase .ds-token-row{grid-template-columns:minmax(0,1fr) auto;column-gap:10px}
  .parity-contract-showcase .ds-token-row>:nth-child(2){min-width:0;overflow-wrap:anywhere;text-align:right}
  .parity-contract-showcase .ds-token-row>:nth-child(3){grid-column:1/-1;text-align:left!important}
  .parity-contract-showcase [style*="120px 100px 1fr 160px"]{grid-template-columns:76px 48px minmax(0,1fr)!important;column-gap:10px!important}
  .parity-contract-showcase [style*="120px 100px 1fr 160px"]>:nth-child(3){min-width:0;overflow-wrap:anywhere}
  .parity-contract-showcase [style*="120px 100px 1fr 160px"]>:nth-child(4){grid-column:1/-1;margin-top:4px;text-align:left!important}
  .parity-contract-showcase [style*="60px 1fr 140px 100px"]{grid-template-columns:36px minmax(0,1fr)!important;column-gap:12px!important}
  .parity-contract-showcase [style*="60px 1fr 140px 100px"]>:nth-child(3),.parity-contract-showcase [style*="60px 1fr 140px 100px"]>:nth-child(4){grid-column:2;text-align:left!important}
}

/* Sidebar variants contain native buttons without shared control classes. */
.sidebar button{box-sizing:border-box;min-height:44px;min-width:44px}
.user-pill{min-width:44px}
